def running_max(xs):
    """Return a list whose i-th value is the largest of xs[0..i]."""
    if not xs:
        return []

    max_so_far = xs[0]
    result = [max_so_far]

    for x in xs[1:]:
        max_so_far = max(max_so_far, x)
        result.append(max_so_far)

    return result

