def mode(xs):
    """Return the most frequent value of a non-empty list; among equally frequent values, the smallest."""
    frequency_map = {}
    for x in xs:
        if x in frequency_map:
            frequency_map[x] += 1
        else:
            frequency_map[x] = 1

    max_frequency = max(frequency_map.values())
    modes = [x for x, freq in frequency_map.items() if freq == max_frequency]

    return min(modes)

