import heapq

def top_k_indices(xs, k):
    # Create a min-heap to store the k largest elements
    heap = []
    for i, x in enumerate(xs):
        if len(heap) < k:
            heapq.heappush(heap, (-x, i))
        elif -x > heap[0][0]:
            heapq.heappop(heap)
            heapq.heappush(heap, (-x, i))

    # Extract the indices from the heap
    return [i for _, i in heap]

