import heapq

def median(xs):
    """Return the median of a non-empty list; for an even count, the mean of the two middle values."""
    half = len(xs) // 2
    lower_half = sorted(heapq.nsmallest(half, xs))
    upper_half = sorted(heapq.nlargest(half, xs), reverse=True)

    if len(xs) % 2 == 0:
        return (lower_half[-1] + upper_half[0]) / 2
    else:
        return upper_half[0]

