def mode(xs):
    """Return the most frequent value of a non-empty list; among equally frequent values, the smallest."""
    frequency_map = {}
    for x in xs:
        if x in frequency_map:
            frequency_map[x] += 1
        else:
            frequency_map[x] = 1

    max_frequency = 0
    most_frequent_values = []
    for x, freq in frequency_map.items():
        if freq > max_frequency:
            max_frequency = freq
            most_frequent_values = [x]
        elif freq == max_frequency:
            most_frequent_values.append(x)

    # If there's more than one value with the same highest frequency,
    # choose the smallest one.
    if len(most_frequent_values) > 1:
        return min(most_frequent_values)
    else:
        return most_frequent_values[0]

