def mode(xs):
    """Return the most frequent value of a non-empty list; among equally frequent values, the smallest."""
    count_map = {}
    for x in xs:
        if x in count_map:
            count_map[x] += 1
        else:
            count_map[x] = 1

    max_count = 0
    modes = []
    for key, value in count_map.items():
        if value > max_count:
            max_count = value
            modes = [key]
        elif value == max_count:
            modes.append(key)

    return min(modes) if modes else None

