def mode(xs):
    if not xs:
        raise ValueError("Input list cannot be empty")

    frequency_map = {}
    for x in xs:
        if x in frequency_map:
            frequency_map[x] += 1
        else:
            frequency_map[x] = 1

    max_frequency = max(frequency_map.values())
    modes = [x for x, freq in frequency_map.items() if freq == max_frequency]

    return min(modes) if len(modes) > 0 else None

