def top_k_indices(xs, k):
    """Return the indices of the k largest values, largest first; equal values are ordered by index."""
    if not xs or k <= 0:
        return []

    # Find the maximum value in the list
    max_val = max(xs)

    # Create a dictionary to count occurrences of each value
    val_counts = {}
    for i, x in enumerate(xs):
        if x == max_val:
            val_counts[i] = val_counts.get(i, 0) + 1

    # Sort the indices based on their occurrence and then by their original position
    sorted_indices = sorted(val_counts.keys(), key=lambda i: (val_counts[i], i))

    # Return the first k indices
    return sorted_indices[:k]

