def argmax(xs):
    """Return the index of the largest value; if several are equal, the smallest such index."""
    if not xs:
        return -1  # Return -1 to indicate empty list

    max_val = xs[0]
    max_index = 0

    for i, val in enumerate(xs):
        if val > max_val:
            max_val = val
            max_index = i
        elif val == max_val:
            if i < max_index:
                max_index = i

    return max_index

