def accuracy(preds, labels):
    """Return the fraction of positions where preds equals labels; both lists have the same non-zero length."""
    if not preds or not labels:
        return 0.0

    # Ensure both lists have the same length
    if len(preds) != len(labels):
        raise ValueError("preds and labels must have the same length")

    # Count the number of positions where preds equals labels
    correct = sum(1 for p, l in zip(preds, labels) if p == l)

    # Calculate the accuracy
    return correct / len(preds)

