def exponential_moving_average(xs, alpha):
    """Return the exponential moving average: the first value is xs[0], then alpha * x + (1 - alpha) * previous."""
    if not xs:
        return []

    result = [xs[0]]
    previous = xs[0]

    for i in range(1, len(xs)):
        previous = alpha * xs[i] + (1 - alpha) * previous
        result.append(previous)

    return result

