def pass_at_k(n, c, k):
    """Return the unbiased pass@k estimate from n samples of which c are correct: 1 - C(n - c, k) / C(n, k)."""
    if n < k:
        return 0.0
    if c < 0 or c > n:
        return 0.0
    if k == 0:
        return 1.0
    # Calculate combinations using math.comb
    from math import comb
    numerator = comb(n - c, k)
    denominator = comb(n, k)
    return 1 - numerator / denominator

