def recall_at_k(ranked, relevant, k):
    """Return the fraction of the non-empty set relevant that appears in the first k items of ranked."""
    # Filter the first k items
    top_k = ranked[:k]

    # Count the number of relevant items in the top k
    relevant_in_top_k = sum(1 for item in top_k if item in relevant)

    # Calculate the fraction
    if relevant_in_top_k == 0:
        return 0.0
    else:
        return relevant_in_top_k / len(relevant)

