def argmax(xs):
    """Return the index of the largest value; if several are equal, the smallest such index."""
    if not xs:
        return -1  # Return -1 to indicate empty list

    max_value = xs[0]
    max_index = 0

    for i, value in enumerate(xs):
        if value > max_value:
            max_value = value
            max_index = i
        elif value == max_value:
            if i < max_index:
                max_index = i

    return max_index

