def brier_score(probs, outcomes):
    """Return the mean squared difference between predicted probabilities and outcomes (0 or 1)."""
    # Check if inputs are lists
    if not (isinstance(probs, list) and isinstance(outcomes, list)):
        raise ValueError("probs and outcomes must be lists")

    # Check if probabilities are in [0, 1]
    if not all(0 <= p <= 1 for p in probs):
        raise ValueError("Probs must be between 0 and 1")

    # Check if outcomes are 0 or 1
    if not all(o in (0, 1) for o in outcomes):
        raise ValueError("Outcomes must be 0 or 1")

    # Calculate the squared differences
    squared_diffs = [(p - o) ** 2 for p, o in zip(probs, outcomes)]

    # Return the mean of squared differences
    return sum(squared_diffs) / len(squared_diffs)

