def moving_average(xs, k):
    """Return the averages of each window of k consecutive values, in order (len(xs) - k + 1 values)."""
    if k <= 0:
        raise ValueError("k must be a positive integer")

    if len(xs) < k:
        raise ValueError("Window size k is larger than the input list")

    result = []
    for i in range(len(xs) - k + 1):
        window = xs[i:i + k]
        average = sum(window) / k
        result.append(average)

    return result

