import heapq

def top_k_indices(xs, k):
    """Return the indices of the k largest values, largest first; equal values are ordered by index."""
    if k == 0:
        return []

    # Use a max-heap to keep track of the k largest elements
    # We'll use a heap where each element is a tuple (-value, index) to simulate a max-heap
    heap = []
    for i, val in enumerate(xs):
        if len(heap) < k:
            heapq.heappush(heap, (-val, i))
        else:
            if -val < heap[0][0]:
                heapq.heappop(heap)
                heapq.heappush(heap, (-val, i))

    # Extract the indices from the heap
    result = [i for (-val, i) in heap]
    return result

