def brier_score(probs, outcomes):
    """Return the Brier score, which is the mean squared difference between predicted probabilities and outcomes (0 or 1)."""
    if len(probs) != len(outcomes):
        raise ValueError("The number of probabilities and outcomes must be the same.")

    # Calculate the squared difference for each pair
    squared_diffs = [(p - o) ** 2 for p, o in zip(probs, outcomes)]

    # Return the mean of the squared differences
    return sum(squared_diffs) / len(squared_diffs)

