def running_max(xs):
    """Return a list whose i-th value is the largest of xs[0..i]."""
    if not xs:
        return []

    result = [xs[0]]
    current_max = xs[0]

    for i in range(1, len(xs)):
        if xs[i] > current_max:
            current_max = xs[i]
        result.append(current_max)

    return result

