def normalize(xs):
    """Return xs scaled so that the values sum to 1. The input sum is non-zero."""
    total_sum = sum(xs)
    if total_sum == 0:
        raise ValueError("The input sum must be non-zero.")
    return [x / total_sum for x in xs]

