def brier_score(probs, outcomes):
    """Return the mean squared difference between predicted probabilities and outcomes (0 or 1)."""
    if not isinstance(outcomes, list) or not all(isinstance(x, int) and x in {0, 1} for x in outcomes):
        raise ValueError("Outcomes must be a list of 0s and 1s.")

    if not isinstance(probs, list) or len(probs) != len(outcomes):
        raise ValueError("Probs must be a list of the same length as outcomes.")

    mse = sum((p - outcome) ** 2 for p, outcome in zip(probs, outcomes))
    return mse / len(outcomes)
