def binom(n, k):
    """Calculate the binomial coefficient C(n, k)."""
    return math.comb(n, k)

def pass_at_k(n, c, k):
    """Return the unbiased pass@k estimate from n samples of which c are correct: 1 - C(n - c, k) / C(n, k)."""
    if k > n:
        raise ValueError("k must be less than or equal to n")
    if k < 0:
        raise ValueError("k must be non-negative")

    # Calculate the number of ways to choose k correct answers out of n
    total_ways = binom(n, k)

    # Calculate the number of ways to choose k correct answers out of (n - c) correct answers
    incorrect_ways = binom(n - c, k)

    # Calculate the pass@k estimate
    pass_at_k_estimate = 1 - incorrect_ways / total_ways

    return pass_at_k_estimate

