import math

def binomial_coefficient(n, k):
    """Calculate the binomial coefficient C(n, k)."""
    return math.comb(n, k)

def pass_at_k(n, c, k):
    """Return the unbiased pass@k estimate from n samples of which c are correct: 1 - C(n - c, k) / C(n, k)."""
    if k > n or k < 0:
        raise ValueError("k must be between 0 and n (inclusive)")

    if c > n or c < 0:
        raise ValueError("c must be between 0 and n (inclusive)")

    if c > n - k:
        raise ValueError("c cannot be greater than n - k")

    if c == 0:
        return 0.0

    if c == n:
        return 1.0

    numerator = binomial_coefficient(n - c, k)
    denominator = binomial_coefficient(n, k)

    return 1 - numerator / denominator
