def mode(xs):
    """Return the most frequent value of a non-empty list; among equally frequent values, the smallest."""
    counter = Counter(xs)
    most_common = counter.most_common()
    if most_common:
        # Find the smallest key with the highest frequency
        for value, count in reversed(most_common):
            if count == most_common[0][1]:
                return value
    else:
        raise ValueError("The list is empty")

