def moving_average(xs, k):
    """Return the averages of each window of k consecutive values, in order (len(xs) - k + 1 values)."""
    if k <= 0 or len(xs) < k:
        raise ValueError("k must be positive and less than or equal to the length of xs")

    result = []
    for i in range(len(xs) - k + 1):
        window = xs[i:i+k]
        average = sum(window) / k
        result.append(round(average, 4))  # Round to 4 decimal places

    return result

