from math import comb

def pass_at_k(n, c, k):
    """Return the unbiased pass@k estimate from n samples of which c are correct: 1 - C(n - c, k) / C(n, k)."""
    if k > n:
        return 1.0
    if c == 0:
        return 0.0
    if c == n:
        return 1.0
    return 1 - comb(n - c, k) / comb(n, k)

