from collections import *

def moving_average(xs, k):
    """Return the averages of each window of k consecutive values, in order (len(xs) - k + 1 values)."""
    if k <= 0:
        raise ValueError("k must be greater than 0")
    if k > len(xs):
        raise ValueError("k must not be greater than the length of xs")

    return [sum(xs[i:i+k]) / k for i in range(len(xs) - k + 1)]

