from typing import *
from collections import *

def argmax(xs):
    """Return the index of the largest value; if several are equal, the smallest such index."""
    max_index = 0
    for i in range(1, len(xs)):
        if xs[i] > xs[max_index]:
            max_index = i
        elif xs[i] == xs[max_index]:
            max_index = min(max_index, i)
    return max_index
```

